	async function convertToPNG(path) {
		const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
		if (!convertToPNG) {
			return path;
		}
		const newPath = await image.normalise(path);
		await file.delete(path);
		return newPath;
	}

	function generateProfileImageFilename(uid, extension) {
		const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
		return `${uid}-profileavatar-${Date.now()}${convertToPNG ? '.png' : extension}`;
	}

	User.getLocalCoverPath = async function (uid) {
		return await getLocalProfileImagePath(uid, 'cover');
	};

	User.getLocalAvatarPath = async function (uid) {
		return await getLocalProfileImagePath(uid, 'avatar');
	};

	User.removeProfileImage = async function (uid) {
		validateUid(uid);
		const userData = await User.getUserFields(uid, ['uploadedpicture', 'picture']);
		const localPath = await User.getLocalAvatarPath(uid);
		await file.delete(localPath);

		await User.setUserFields(uid, {
			uploadedpicture: '',
			picture: userData.picture === userData.uploadedpicture ? '' : userData.picture,
		});
		return {
			uploadedpicture: userData.uploadedpicture,
			picture: userData.picture,
		};
	};

	User.removeCoverPicture = async function (uid) {
		validateUid(uid);
		const localPath = await User.getLocalCoverPath(uid);
		await file.delete(localPath);
		await db.deleteObjectFields(`user:${uid}`, ['cover:url', 'cover:position']);
		return { success: true };
	};

	async function getLocalProfileImagePath(uid, type) {
		validateUid(uid);
		const field = type === 'cover' ? 'cover:url' : 'uploadedpicture';
		const url = await User.getUserField(uid, field);
		const relativePath = (nconf.get('relative_path') || '').replace(/\/$/, '');
		const urlPrefix = `${relativePath}/assets/uploads/profile/`;
		if (typeof url !== 'string' || !url.startsWith(urlPrefix)) {
			return false;
		}

		const filename = url.slice(urlPrefix.length);
		const imageName = `${uid}-profile${type}`;
		const imagePattern = new RegExp(`^${imageName}(?:-[^/]+)?\\.(${profileExtensions.join('|')})$`, 'i');
		if (!imagePattern.test(filename) || filename !== path.basename(filename) || filename.includes('?') || filename.includes('#')) {
			return false;
		}

		const profilePath = path.resolve(nconf.get('upload_path'), 'profile');
		const localPath = path.resolve(profilePath, filename);
		if (path.dirname(localPath) !== profilePath || !(await file.exists(localPath))) {
			return false;
		}
		return localPath;
	}

	function validateUid(uid) {
		if (!/^\d+$/.test(String(uid)) || Number(uid) <= 0) {
			throw new Error('[[error:invalid-uid]]');
		}
	}
};

